(() => {
  'use strict';
  const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const norm = v => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
  const list = v => Array.isArray(v) ? v : [];
  const stages = {confirmadas:'Confirmadas',emitidas:'Emitidas',andamento:'Em andamento',finalizadas:'Finalizadas'};
  const date = v => /^\d{4}-\d{2}-\d{2}$/.test(v||'') ? v.split('-').reverse().join('/') : 'Não informada';
  const money = v => Number.isFinite(Number(v)) && v !== '' && v != null ? Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}) : 'Não informado';
  const linked = (t,id) => t.client===id || list(t.participants).includes(id);
  function select(state,type,f={}) {
    const clients=list(state.clients), trips=list(state.trips);
    let rows=type==='clients'?clients.filter(c=>f.scope==='filtered'&&f.status==='deleted'?!!c.deletedAt:!c.deletedAt):trips.filter(t=>window.TravelWorkflow.category(t));
    if(f.scope==='filtered')rows=rows.filter(r=>{
      if(type==='clients')return (!f.status||f.status==='deleted'||(r.status||'Ativo')===f.status)&&(!f.relationship||r.relationship===f.relationship)&&norm([r.name,r.phone,r.email].join(' ')).includes(norm(f.query));
      const names=clients.filter(c=>linked(r,c.id)).map(c=>c.name).join(' ');
      return (!f.stage||window.TravelWorkflow.category(r)===f.stage)&&(!f.client||linked(r,f.client))&&norm([r.title,r.destination,names].join(' ')).includes(norm(f.query))&&(!(f.from||f.to)||(!r.datesPending&&/^\d{4}-\d{2}-\d{2}$/.test(r.start||'')&&(!f.from||(r.end||r.start)>=f.from)&&(!f.to||r.start<=f.to)));
    });
    return [...rows].sort((a,b)=>type==='clients'?String(a.name||'').localeCompare(String(b.name||''),'pt-BR'):String(a.start||'9999').localeCompare(String(b.start||'9999')));
  }
  function describe(state,type,f){
    if(f.scope!=='filtered')return type==='clients'?'Todos os clientes, exceto excluídos':'Todas as viagens confirmadas, emitidas, em andamento e finalizadas';
    return ['Filtros personalizados',f.query&&'Busca: '+f.query,f.status&&(f.status==='deleted'?'Excluídos':f.status),f.relationship,f.stage&&stages[f.stage],f.client&&'Cliente: '+(list(state.clients).find(c=>c.id===f.client)?.name||'Não identificado'),f.from&&'De '+date(f.from),f.to&&'Até '+date(f.to)].filter(Boolean).join(' · ');
  }
  const pairs = values => '<dl>'+values.map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v==null||v===''?'Não informado':v)+'</dd></div>').join('')+'</dl>';
  function html(state,type,f={},now=new Date()) {
    const rows=select(state,type,f), clients=list(state.clients), trips=list(state.trips), docs=list(state.documents);
    const clientName=id=>clients.find(c=>c.id===id)?.name||'Cliente não identificado';
    const title=type==='clients'?'Relatório de clientes':'Relatório de viagens';
    const summary=type==='clients'?[['Clientes',rows.length],['Fidelizados',rows.filter(c=>c.relationship==='Fidelizado').length],['Sem contato',rows.filter(c=>!c.email&&!c.phone).length]]:[['Viagens',rows.length],['Viajantes informados',rows.reduce((n,t)=>n+(Number(t.travelers)||0),0)],['Valor cadastrado',money(rows.reduce((n,t)=>n+(Number(t.value)||0),0))]];
    const header=type==='clients'?['Cliente','Contato','Situação','Relacionamento']:['Viagem / destino','Cliente','Período','Etapa / valor'];
    const table=rows.map(r=>type==='clients'?[r.name,[r.email,r.phone].filter(Boolean).join(' / '),r.deletedAt?'Excluído':r.status||'Ativo',r.relationship||'Não avaliado']:[r.title+' · '+(r.destination||'Destino a confirmar'),clientName(r.client),r.datesPending?'Datas a confirmar':date(r.start)+' — '+date(r.end),stages[window.TravelWorkflow.category(r)]+' · '+money(r.value)]);
    const details=rows.map((r,i)=>{
      const related=type==='clients'?trips.filter(t=>linked(t,r.id)):[];
      const documents=docs.filter(d=>type==='clients'?list(d.clients).includes(r.id):d.trip===r.id);
      const fields=type==='clients'?[['Situação',r.deletedAt?'Excluído':r.status||'Ativo'],['E-mail',r.email],['Telefone',r.phone],['Nascimento',date(r.birthDate)],['Endereço',r.address],['Documento', [r.documentType,r.documentNumber].filter(Boolean).join(' · ')],['Validade',date(r.documentExpiry)],['Origem',r.acquisitionSource],['Indicado por',r.referredBy?clientName(r.referredBy):'Não informado'],['Relacionamento',r.relationship]]:[['Destino',r.destination],['Titular',clientName(r.client)],['Etapa',stages[window.TravelWorkflow.category(r)]],['Status registrado',r.status],['Saída',r.datesPending?'A confirmar':date(r.start)],['Retorno',r.datesPending?'A confirmar':date(r.end)],['Viajantes',r.travelers],['Valor cadastrado',money(r.value)],['Participantes',list(r.participants).map(clientName).join(', ')],['Reserva',({confirmed:'Confirmada',pending:'Pendente'})[r.sales?.fulfillment?.reservation]||'Não informada'],['Emissão',({issued:'Emitida',pending:'Pendente'})[r.sales?.fulfillment?.emission]||'Não informada']];
      return '<article><div class="record-title"><span>'+String(i+1).padStart(2,'0')+'</span><h2>'+esc(type==='clients'?r.name:r.title)+'</h2></div>'+pairs(fields)+(type==='clients'?list(r.identityDocuments).map(d=>pairs([['Documento adicional',d.type],['Número',d.number],['Emissão',date(d.issued)],['Validade',date(d.expiry)],['Órgão / categoria',d.issuer||d.category]])).join(''):'')+(r.notes?'<h3>Observações e preferências</h3><p class="notes">'+esc(r.notes)+'</p>':'')+(related.length?'<h3>Atendimentos e viagens vinculados</h3><ul>'+related.map(t=>'<li>'+esc([t.title,t.destination,t.status,date(t.start)+' — '+date(t.end)].filter(Boolean).join(' · '))+'</li>').join('')+'</ul>':'')+(documents.length?'<h3>Documentos cadastrados</h3><ul>'+documents.map(d=>'<li>'+esc(d.name)+(d.expiry?' · validade '+esc(date(d.expiry)):'')+'</li>').join('')+'</ul>':'')+'</article>';
    }).join('');
    return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>'+esc(title)+'</title><style>'+style+'</style></head><body><header><div class="brand">travel<span>pro</span></div><p>'+esc(state.agency||'Sua agência')+'</p><h1>'+title+'</h1><div class="meta">Emitido em '+esc(now.toLocaleString('pt-BR'))+'<br>'+esc(describe(state,type,f))+'</div></header><section class="summary">'+summary.map(([k,v])=>'<div><strong>'+esc(v)+'</strong><span>'+esc(k)+'</span></div>').join('')+'</section>'+(type==='trips'?'<p class="fine">Valores cadastrados nas viagens. Não representam recebimentos, lucro ou saldo financeiro. O período filtra viagens que coincidem com as datas escolhidas; datas pendentes ficam fora desse filtro.</p>':'')+(rows.length?'<h2>Visão geral</h2><table><thead><tr>'+header.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+table.map(row=>'<tr>'+row.map(v=>'<td>'+esc(v||'Não informado')+'</td>').join('')+'</tr>').join('')+'</tbody></table>'+(f.layout==='summary'?'':'<section class="details"><h2>Detalhamento</h2>'+details+'</section>'):'<p class="empty">Nenhum registro corresponde aos filtros selecionados.</p>')+'<footer>'+esc(state.agency||'TravelPro')+' · Relatório interno · '+rows.length+' registros</footer></body></html>';
  }
  const style=`@page{size:A4;margin:16mm}*{box-sizing:border-box}body{margin:0 auto;max-width:1000px;padding:32px;font:12px/1.55 Arial,sans-serif;color:#28333d;background:#fff}header{border-bottom:3px solid #06a99a;padding-bottom:22px}header p{margin:12px 0 4px;color:#5c6973}.brand{font-size:25px;font-weight:800;letter-spacing:-1px}.brand span{color:#009b93}h1{font-size:30px;margin:5px 0 12px;letter-spacing:-1px}h2{font-size:18px;margin:24px 0 12px}h3{font-size:12px;margin:16px 0 6px;color:#006c71}.meta,.fine{color:#63717a;font-size:11px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:22px 0}.summary div{padding:16px;background:#f0f6f5;border:1px solid #dce9e6;border-radius:10px}.summary strong,.summary span{display:block}.summary strong{font-size:23px;color:#006c71}.summary span{font-size:11px;margin-top:3px}table{border-collapse:collapse;width:100%;table-layout:fixed}thead{display:table-header-group}th{text-align:left;background:#edf3f4;font-size:10px;text-transform:uppercase;letter-spacing:.4px}td,th{padding:10px 8px;border-bottom:1px solid #dce3e5;vertical-align:top;overflow-wrap:anywhere}tr{break-inside:avoid}article{border-top:1px solid #d7e1e3;padding:16px 0;break-inside:auto}.record-title{display:flex;gap:12px;align-items:center;break-after:avoid}.record-title>span{background:#e9f4f0;color:#087f71;border-radius:7px;padding:6px 10px}.record-title h2{margin:0}dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 24px}dl>div{break-inside:avoid}dt{font-size:10px;color:#63717a}dd{margin:2px 0 0;overflow-wrap:anywhere}.notes{white-space:pre-wrap;overflow-wrap:anywhere}li{margin:6px 0;overflow-wrap:anywhere}ul{padding-left:18px}footer{border-top:1px solid #dce3e5;margin-top:24px;padding-top:12px;font-size:10px;color:#63717a}.empty{padding:35px 0}.details>h2{break-after:avoid}@media print{body{padding:0;max-width:none}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}h2,h3{break-after:avoid}article{orphans:3;widows:3}}`;
  function mount(root,{state,type,initial={}}){
    const option=(value,label)=>'<option value="'+esc(value)+'">'+esc(label)+'</option>';
    const field=(label,content)=>'<label class="form-field"><span>'+label+'</span>'+content+'</label>';
    root.innerHTML='<div class="report-controls">'+field('Registros','<select name="scope"><option value="all">Todos os registros</option><option value="filtered">Aplicar filtros</option></select>')+field('Apresentação','<select name="layout"><option value="full">Completo: resumo e fichas detalhadas</option><option value="summary">Resumido: indicadores e tabela</option></select>')+'<div class="report-filters form-grid" hidden>'+field('Buscar','<input name="query" type="search" placeholder="'+(type==='clients'?'Nome, e-mail ou telefone':'Viagem, destino ou cliente')+'">')+(type==='clients'?field('Situação','<select name="status">'+option('','Todas as situações')+['Ativo','Prospect','Inativo'].map(v=>option(v,v)).join('')+option('deleted','Excluídos')+'</select>')+field('Relacionamento','<select name="relationship">'+option('','Todos')+['Em construção','Próximo','Fidelizado','Requer atenção'].map(v=>option(v,v)).join('')+'</select>'):field('Etapa','<select name="stage">'+option('','Todas as etapas')+Object.entries(stages).map(([v,l])=>option(v,l)).join('')+'</select>')+field('Cliente / participante','<select name="client">'+option('','Todos os clientes')+list(state.clients).map(c=>option(c.id,c.name)).join('')+'</select>')+field('Período: de','<input type="date" name="from">')+field('Até','<input type="date" name="to">'))+'</div><p class="form-hint">'+(type==='clients'?'Todos inclui ativos, prospects e inativos. Excluídos estão disponíveis no filtro de situação.':'Inclui as viagens da seção Viagens. O período considera saída e retorno; atendimentos ainda em negociação não entram.')+'</p><p data-report-count role="status"></p><p data-report-error role="alert" hidden></p><div class="dialog-actions"><button type="button" class="primary-button" data-report-print>Imprimir / salvar PDF</button></div><p class="form-hint">Na janela de impressão, escolha “Salvar como PDF”. Os anexos são listados pelo nome; seu conteúdo não é incluído.</p></div><iframe class="report-preview" title="Prévia do relatório" sandbox="allow-same-origin allow-modals"></iframe>';
    const controls=root.querySelector('.report-controls'),frame=root.querySelector('iframe'),print=root.querySelector('[data-report-print]'),error=root.querySelector('[data-report-error]');
    for(const [k,v] of Object.entries(initial)){const input=controls.querySelector('[name="'+k+'"]');if(input)input.value=v;}
    let valid=false,ready=false;
    frame.addEventListener('load',()=>{ready=true;print.disabled=!valid;});
    const update=()=>{
      const f=Object.fromEntries([...controls.querySelectorAll('[name]')].map(el=>[el.name,el.value]));
      root.querySelector('.report-filters').hidden=f.scope!=='filtered';
      const invalid=f.scope==='filtered'&&f.from&&f.to&&f.from>f.to;
      const rows=select(state,type,f);valid=!invalid&&rows.length>0;ready=false;print.disabled=true;
      error.hidden=!invalid;error.textContent=invalid?'A data final precisa ser igual ou posterior à data inicial.':'';
      root.querySelector('[data-report-count]').textContent=invalid?'Revise o período.':rows.length+' registros no relatório';
      frame.srcdoc=invalid?'<!doctype html><p>Revise o período para visualizar o relatório.</p>':html(state,type,f);
    };
    let timer;controls.addEventListener('input',()=>{clearTimeout(timer);valid=false;print.disabled=true;timer=setTimeout(update,200);});controls.addEventListener('change',()=>{clearTimeout(timer);update();});
    print.addEventListener('click',()=>{if(!valid||!ready)return;frame.contentWindow.focus();frame.contentWindow.print();});update();
  }
  window.TravelReports={select,html,mount};
})();
